   129	    void append_null(CharVector & out) const
   130	    {
   131	      const char nul[4] = {0,0,0,0}; // 4 should be enough
   132	      out.write(nul, null_len_);
   133	    }
   134	
   135	    unsigned int null_len() const {return null_len_;}
   136	  
   137	    // this filters will generally not translate null characters
   138	    // if you need a null character at the end, add it yourself
   139	    // with append_null
   140	
   141	    void decode(const char * in, int size, FilterCharVector & out) const 
   142	      {decode_->decode(in,size,out);}
   143	    
   144	    void encode(const FilterChar * in, const FilterChar * stop, 
   145	                CharVector & out) const
   146	      {encode_->encode(in,stop,out);}
   147	
