   152	    // does NOT pass it through filters
   153	    // DOES NOT use an internal state
   154	    void convert(const char * in, int size, CharVector & out, ConvertBuffer & buf) const
   155	    {
   156	      if (conv_) {
   157	        conv_->convert(in,size,out);
   158	      } else {
   159	        buf.clear();
   160	        decode_->decode(in, size, buf);
   161	        encode_->encode(buf.pbegin(), buf.pend(), out);
   162	      }
   163	    }
   164	
   165	    // does NOT pass it through filters
   166	    // DOES NOT use an internal state
   167	    PosibErr<void> convert_ec(const char * in, int size, CharVector & out, 
   168	                              ConvertBuffer & buf, ParmStr orig) const
   169	    {
   170	      if (conv_) {
   171	        RET_ON_ERR(conv_->convert_ec(in,size,out, orig));
   172	      } else {
   173	        buf.clear();
   174	        RET_ON_ERR(decode_->decode_ec(in, size, buf, orig));
   175	       RET_ON_ERR(encode_->encode_ec(buf.pbegin(), buf.pend(), 
   176	                                      out, orig));
   177	      }
   178	      return no_err;
   179	    }
